CodeAssembler& CodeAssemblerFns1::jmp(AsmMemoryOperand op0) {
	Code code;
	if (op0.size() == MemoryOperandSize::Tbyte) {
		code = Code::Jmp_m1664;
	} else if (op0.size() == MemoryOperandSize::Qword) {
		code = Code::Jmp_rm64;
	} else if (op0.size() == MemoryOperandSize::Fword) {
		code = Code::Jmp_m1632;
	} else if (op0.size() == MemoryOperandSize::Dword) {
		if (bitness() >= 32) {
			code = Code::Jmp_rm32;
		} else {
			code = Code::Jmp_m1616;
		}
	} else if (op0.size() == MemoryOperandSize::Word) {
		code = Code::Jmp_rm16;
	} else {
		return set_error("jmp: invalid operands");
	}
	return add_instr(Instruction::with1(code, to_memory_operand(op0)));
}

