CodeAssembler& CodeAssemblerFns1::or_(AsmRegister8 op0, std::int32_t op1) {
	const Code code = op0.register_() == Register::AL ? Code::Or_AL_imm8 : Code::Or_rm8_imm8;
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmRegister16 op0, std::int32_t op1) {
	Code code;
	if (op0.register_() == Register::AX) {
		code = Code::Or_AX_imm16;
	} else if ((op1 >= -0x80 && op1 <= 0x7F)) {
		code = Code::Or_rm16_imm8;
	} else {
		code = Code::Or_rm16_imm16;
	}
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmRegister32 op0, std::int32_t op1) {
	Code code;
	if (op0.register_() == Register::EAX) {
		code = Code::Or_EAX_imm32;
	} else if ((op1 >= -0x80 && op1 <= 0x7F)) {
		code = Code::Or_rm32_imm8;
	} else {
		code = Code::Or_rm32_imm32;
	}
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmRegister64 op0, std::int32_t op1) {
	Code code;
	if (op0.register_() == Register::RAX) {
		code = Code::Or_RAX_imm32;
	} else if ((op1 >= -0x80 && op1 <= 0x7F)) {
		code = Code::Or_rm64_imm8;
	} else {
		code = Code::Or_rm64_imm32;
	}
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmMemoryOperand op0, std::int32_t op1) {
	Code code;
	if (op0.size() == MemoryOperandSize::Qword) {
		if ((op1 >= -0x80 && op1 <= 0x7F)) {
			code = Code::Or_rm64_imm8;
		} else {
			code = Code::Or_rm64_imm32;
		}
	} else if (op0.size() == MemoryOperandSize::Dword) {
		if ((op1 >= -0x80 && op1 <= 0x7F)) {
			code = Code::Or_rm32_imm8;
		} else {
			code = Code::Or_rm32_imm32;
		}
	} else if (op0.size() == MemoryOperandSize::Word) {
		if ((op1 >= -0x80 && op1 <= 0x7F)) {
			code = Code::Or_rm16_imm8;
		} else {
			code = Code::Or_rm16_imm16;
		}
	} else if (op0.size() == MemoryOperandSize::Byte) {
		code = Code::Or_rm8_imm8;
	} else {
		return set_error("or: invalid operands");
	}
	return add_instr(Instruction::with2(code, to_memory_operand(op0), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmRegister8 op0, std::uint32_t op1) {
	const Code code = op0.register_() == Register::AL ? Code::Or_AL_imm8 : Code::Or_rm8_imm8;
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmRegister16 op0, std::uint32_t op1) {
	Code code;
	if (op0.register_() == Register::AX) {
		code = Code::Or_AX_imm16;
	} else if ((op1 <= 0x7FU || (0xFF80U <= op1 && op1 <= 0xFFFFU))) {
		code = Code::Or_rm16_imm8;
	} else {
		code = Code::Or_rm16_imm16;
	}
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmRegister32 op0, std::uint32_t op1) {
	Code code;
	if (op0.register_() == Register::EAX) {
		code = Code::Or_EAX_imm32;
	} else if ((op1 <= 0x7FU || 0xFFFFFF80U <= op1)) {
		code = Code::Or_rm32_imm8;
	} else {
		code = Code::Or_rm32_imm32;
	}
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns1::or_(AsmMemoryOperand op0, std::uint32_t op1) {
	Code code;
	if (op0.size() == MemoryOperandSize::Dword) {
		if ((op1 <= 0x7FU || 0xFFFFFF80U <= op1)) {
			code = Code::Or_rm32_imm8;
		} else {
			code = Code::Or_rm32_imm32;
		}
	} else if (op0.size() == MemoryOperandSize::Word) {
		if ((op1 <= 0x7FU || (0xFF80U <= op1 && op1 <= 0xFFFFU))) {
			code = Code::Or_rm16_imm8;
		} else {
			code = Code::Or_rm16_imm16;
		}
	} else if (op0.size() == MemoryOperandSize::Byte) {
		code = Code::Or_rm8_imm8;
	} else {
		return set_error("or: invalid operands");
	}
	return add_instr(Instruction::with2(code, to_memory_operand(op0), op1));
}

